#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    long long q;
    cin >> n >> m >> q;
    vector<vector<long long>> g(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
        }
    }
    vector<vector<long long>> qs(q, vector<long long>(4));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 4; j++) {
            cin >> qs[i][j];
        }
    }

    vector<vector<long long>> p(n + 1, vector<long long>(m + 1, 0));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            p[i][j] = g[i - 1][j - 1] + p[i - 1][j] + p[i][j - 1] - p[i - 1][j - 1];
        }
    }
    for (int k = 0; k < q; k++) {
        long long r1 = qs[k][0], c1 = qs[k][1], r2 = qs[k][2], c2 = qs[k][3];
        cout << p[r2][c2] - p[r1 - 1][c2] - p[r2][c1 - 1] + p[r1 - 1][c1 - 1] << "\n";
    }

    return 0;
}

