import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[][] g = new long[(int) n][(int) m];
        for (int i = 0; i < g.length; i++) {
            for (int j = 0; j < g[i].length; j++) {
                g[i][j] = Long.parseLong(next());
            }
        }
        long[][] qs = new long[(int) q][4];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        long[][] p = new long[(int) n + 1][(int) m + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                p[i][j] = g[i - 1][j - 1] + p[i - 1][j] + p[i][j - 1] - p[i - 1][j - 1];
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            int r1 = (int) qs[k][0], c1 = (int) qs[k][1], r2 = (int) qs[k][2], c2 = (int) qs[k][3];
            sb.append(p[r2][c2] - p[r1 - 1][c2] - p[r2][c1 - 1] + p[r1 - 1][c1 - 1]).append("\n");
        }
        System.out.print(sb);
    }
}
